begin;create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table behavior_fixture(pack uuid,reference uuid,programme uuid);grant select,insert,update on behavior_fixture to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','cf100000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Runtime behavior course','School source','PUBLISHED');
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
insert into behavior_fixture(pack)select(internal.configure_curriculum('version.create',null,'{"packId":"runtime-school-source","kind":"school_custom","framework":"School Custom","programme":"Runtime school source","version":"school-1","scope":"synthetic","sourceStatus":"VERIFIED","rightsStatus":"PERMITTED","sourceLocation":"repo:school-source","sourceChecksum":null,"synthetic":true,"reason":"School-authored technical behavior"}','behavior-pack',repeat('a',64),'behavior')->>'id')::uuid;
update behavior_fixture set reference=(internal.configure_curriculum('reference.create',null,jsonb_build_object('packVersionId',pack,'parentId',null,'type','objective','title','School behavior objective','description','Explain the school check','code',null,'sequence',1,'subjectId',null,'yearGroupId',null),'behavior-ref',repeat('b',64),'behavior')->>'id')::uuid;
select internal.transition_curriculum_lifecycle((select pack from behavior_fixture),'{"state":"APPROVED","expectedRevision":1,"reviewBasis":"SCHOOL_AUTHORED","artifactDirectory":null,"replacementVersionId":null,"reason":"Reviewed school source","confirmTransition":true}',null,'behavior-approved',repeat('c',64),'behavior');select internal.transition_curriculum_lifecycle((select pack from behavior_fixture),'{"state":"ACTIVE","expectedRevision":2,"reviewBasis":"SCHOOL_AUTHORED","artifactDirectory":null,"replacementVersionId":null,"reason":"Reviewed school activation","confirmTransition":true}',null,'behavior-active',repeat('d',64),'behavior');
update behavior_fixture set programme=(internal.configure_curriculum('programme.create',null,jsonb_build_object('packVersionId',pack,'name','School behavior class','classId','30000000-0000-4000-8000-000000000001','subjectId','43000000-0000-4000-8000-000000000001','yearGroupId','42000000-0000-4000-8000-000000000001','confirmConfiguration',true),'behavior-programme',repeat('e',64),'behavior')->>'id')::uuid;
select internal.configure_curriculum('course.configure','cf100000-0000-4000-8000-000000000001',jsonb_build_object('programmeId',(select programme from behavior_fixture),'referenceId',(select reference from behavior_fixture),'expectedVersion',1,'confirmConfiguration',true),'behavior-course',repeat('f',64),'behavior');
select is(internal.read_course_curriculum_behavior('cf100000-0000-4000-8000-000000000001')->>'basis','SCHOOL_AUTHORED','Explicit school-reviewed source does not invent locked artifact behavior');
select lives_ok($$select internal.accept_curriculum_behavior((select pack from behavior_fixture),'{"reviewBasis":"SCHOOL_AUTHORED","artifactDirectory":null,"expectedLifecycleRevision":3,"reason":"Reviewed explicit school behavior basis","confirmAcceptance":true}','{"basis":"SCHOOL_AUTHORED","version":"school-1","models":["numeric","rubric"],"numericMaxScore":null,"rubric":null,"directory":null,"digest":null}','behavior-accept',repeat('a',64),'behavior')$$,'School-authored behavior acceptance records exact reviewed basis');
select throws_ok($$select internal.accept_curriculum_behavior((select pack from behavior_fixture),'{"reviewBasis":"LOCKED_ARTIFACT","artifactDirectory":"missing","expectedLifecycleRevision":3,"reason":"Missing locked provenance","confirmAcceptance":true}','{"basis":"LOCKED_ARTIFACT","version":"school-1","models":["numeric"],"numericMaxScore":10,"rubric":{},"directory":"missing","digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}','behavior-denied',repeat('b',64),'behavior')$$,'22023',null,'Invented locked behavior cannot replace school-owned source');
reset role;
select throws_ok($$update app.curriculum_behavior_acceptances set reason='Overwrite'where version_id=(select pack from behavior_fixture)$$,'55000',null,'Accepted native source behavior immutable');
select ok(not has_table_privilege('cuevo_api','app.curriculum_behavior_acceptances','SELECT')and not has_function_privilege('authenticated','internal.accept_curriculum_behavior(uuid,jsonb,jsonb,text,text,text)','EXECUTE'),'No raw browser behavior authority');
select*from finish();rollback;
